 if($targetPol==='')setEventMessages('Choose the POL to assign.',null,'errors');elseif($country!==''&&!preg_match('/^[A-Z]{2}$/',$country))setEventMessages('Invalid country filter.',null,'errors');else{$where=array("entity=".(int)$conf->entity,"(pol='UNKNOWN' OR pol='' OR pol IS NULL)");if($country!=='')$where[]="destination_country='".$db->escape($country)."'";if($pod!=='')$where[]="pod='".$db->escape($pod)."'";if($line!=='')$where[]="shipping_line='".$db->escape($line)."'";if($container!=='')$where[]="container_type='".$db->escape($container)."'";if(!$includeHistory)$where[]="is_current=1";$count=0;$countRes=$db->query("SELECT COUNT(*) total FROM ".MAIN_DB_PREFIX."chinaplanetsp_rate WHERE ".implode(' AND ',$where));if($countRes&&($countRow=$db->fetch_object($countRes)))$count=(int)$countRow->total;$sql="UPDATE ".MAIN_DB_PREFIX."chinaplanetsp_rate SET pol='".$db->escape($targetPol)."',public_visible=CASE WHEN destination_country IS NOT NULL AND destination_country<>'' AND shipping_line<>'UNKNOWN' THEN 1 ELSE public_visible END WHERE ".implode(' AND ',$where);if($db->query($sql))setEventMessages($count.' price rows assigned to '.$targetPol.'.',null,'mesgs');else setEventMessages($db->lasterror(),null,'errors');}
